// onDatabaseConfig implements "tsh db config" command.
func onDatabaseConfig(cf *CLIConf) {
	tc, err := makeClient(cf, false)
	if err != nil {
		utils.FatalError(err)
	}
	profile, err := client.StatusCurrent("", cf.Proxy)
	if err != nil {
